"""Build exact vector title atlases and the runtime registry from one replacement contract.
No raster source is modified. Requires fonttools and NotoSansCJK-Bold.ttc.
"""
from pathlib import Path
import json,hashlib
from fontTools.ttLib import TTFont
from fontTools.pens.svgPathPen import SVGPathPen
ROOT=Path(__file__).resolve().parents[1]
PATH=ROOT/'assets/records/brave_guy_character-art.json'
data=json.loads(PATH.read_text())
fonts={lang:TTFont('/usr/share/fonts/opentype/noto/NotoSansCJK-Bold.ttc',fontNumber=index) for lang,index in [('zh-Hant',3),('en',0),('ja',0)]}

def lettering(text,lang):
 font=fonts[lang];glyphs=font.getGlyphSet();cmap=font.getBestCmap();advance=0;paths=[]
 for char in text:
  assert ord(char) in cmap, f'Missing glyph {char}'
  name=cmap[ord(char)];pen=SVGPathPen(glyphs);glyphs[name].draw(pen)
  paths.append(f'<path transform="translate({advance} 0)" d="{pen.getCommands()}"/>')
  advance+=font['hmtx'][name][0]
 scale=min(0.118,1020/advance);x=(1200-advance*scale)/2
 return f'<g transform="translate({x:.3f} {180+380*scale:.3f}) scale({scale:.6f} {-scale:.6f})">'+''.join(paths)+'</g>'

for id,c in data['characters'].items():
 bright,mid,dark=c['palette'];parts=['<svg xmlns="http://www.w3.org/2000/svg" width="3600" height="1440" viewBox="0 0 3600 1440">',f'<title>{c["name"]} — four skills, Traditional Chinese / English / Japanese</title>',f'<defs><linearGradient id="letter" x1="0" y1="0" x2="0" y2="1" gradientUnits="objectBoundingBox"><stop stop-color="{dark}"/><stop offset=".45" stop-color="{mid}"/><stop offset=".52" stop-color="{bright}"/><stop offset="1" stop-color="#ffffff"/></linearGradient><linearGradient id="plate"><stop stop-color="{dark}"/><stop offset=".5" stop-color="{mid}"/><stop offset="1" stop-color="{dark}"/></linearGradient></defs>']
 for row,labels in enumerate(c['titles']['labels']):
  for col,(lang,text) in enumerate(zip(data['title_grid']['columnsByLanguage'],labels)):
   ident=f'letters-{row}-{col}';glyph=lettering(text,lang)
   parts += [f'<svg x="{col*1200}" y="{row*360}" width="1200" height="360" viewBox="0 0 1200 360"><title>{text}</title><defs><g id="{ident}">{glyph}</g></defs>', '<path d="M58 182 112 130 92 78 320 101 460 40 586 86 804 43 818 90 1090 72 1056 127 1150 162 1100 206 1124 270 873 250 730 314 610 266 364 310 350 265 85 280 128 226Z" fill="#10101d" stroke="#05050c" stroke-width="16" stroke-linejoin="round"/>',f'<path d="M80 180 143 135 126 103 340 123 468 66 590 110 787 68 795 113 1063 96 1026 137 1120 163 1071 198 1092 244 863 228 730 288 612 242 383 286 371 241 115 252 156 221Z" fill="url(#plate)" stroke="{bright}" stroke-width="4"/>',f'<g transform="translate(8 11)"><use href="#{ident}" fill="#070713" stroke="#070713" stroke-width="125" stroke-linejoin="round"/></g>',f'<use href="#{ident}" fill="url(#letter)" stroke="#11101b" stroke-width="70" stroke-linejoin="round" paint-order="stroke fill"/>',f'<use href="#{ident}" fill="url(#letter)" stroke="{bright}" stroke-width="9" stroke-linejoin="round" paint-order="stroke fill"/>','</svg>']
 parts.append('</svg>');dest=ROOT/c['titles']['source'];dest.write_text(''.join(parts));c['titles']['sha256']=hashlib.sha256(dest.read_bytes()).hexdigest()
PATH.write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
(ROOT/'js/character-art-data.js').write_text('// Generated by tools/build_character_art.py; edit assets/records/brave_guy_character-art.json.\nexport const CHARACTER_ART='+json.dumps(data,ensure_ascii=False,indent=1)+';\n')
print('Built 3 vector atlases (36 exact multilingual titles), validated all glyphs, generated registry.')
